ALTER TABLE "settings" ADD COLUMN "listing_ranking_criteria" jsonb DEFAULT '[{"id":"role-fit","label":"Rollen-Fit","description":"Wie direkt passt die ausgeschriebene Rolle zu den Zielrollen und zum Profil?","weight":5},{"id":"qualification-fit","label":"Anforderungen/Qualifikation","description":"Wie gut sind Pflichtanforderungen, Ausbildung, Skills und Zertifikate erfüllt?","weight":4},{"id":"experience","label":"Erfahrung","description":"Wie gut passt die vorhandene relevante Erfahrung zu Seniorität und Berufsjahren?","weight":3},{"id":"language","label":"Sprache","description":"Wie gut passen Deutsch- und weitere Sprachkenntnisse zu den Anforderungen?","weight":3},{"id":"location-work-model","label":"Ort/Arbeitsmodell","description":"Wie gut passen Ort, Suchort, Anfahrt, Arbeitszeit und Arbeitsmodell?","weight":3}]'::jsonb NOT NULL;--> statement-breakpoint
ALTER TABLE "settings" ADD COLUMN "lead_ranking_criteria" jsonb DEFAULT '[{"id":"industry-role-fit","label":"Branchen-/Rollen-Fit","description":"Beschäftigt ein Betrieb dieser Art plausibel Personen für die Zielrollen?","weight":5},{"id":"profile-fit","label":"Profil-Passung","description":"Wie gut passen Skills, Erfahrung, Ausbildung und Sprachen grundsätzlich zum Betrieb?","weight":4},{"id":"distance","label":"Entfernung","description":"Wie günstig ist die Entfernung vom Wohnort für eine realistische Bewerbung?","weight":3},{"id":"application-chance","label":"Bewerbungschance","description":"Wie wahrscheinlich ist eine sinnvolle Initiativbewerbung trotz fehlender Ausschreibung?","weight":3}]'::jsonb NOT NULL;--> statement-breakpoint
